import Foundation
import SwiftUI

/// The built-in illustrations an art block draws: shapes on a 400×260
/// canvas, coloured from the theme (Resources/paywall-art.json, generated by
/// cashier-cloud's scripts/art-gen.mjs — the web SDK draws the same data).
enum PaywallArt {
    static let width: CGFloat = 400
    static let height: CGFloat = 260

    struct Gradient: Decodable, Equatable, Sendable {
        let type: String
        let angle: Double
        let stops: [String]
    }

    /// A colour token, a gradient, or "none".
    enum Paint: Decodable, Equatable, Sendable {
        case token(String)
        case linear(Gradient)

        init(from decoder: Decoder) throws {
            let c = try decoder.singleValueContainer()
            if let s = try? c.decode(String.self) { self = .token(s) } else { self = .linear(try c.decode(Gradient.self)) }
        }
    }

    struct Shape: Decodable, Equatable, Sendable {
        let t: String
        var x: Double?, y: Double?, w: Double?, h: Double?, r: Double?
        var cx: Double?, cy: Double?, rx: Double?, ry: Double?
        var d: String?
        var rot: Double?
        var fill: Paint?
        var stroke: String?
        var sw: Double?
        var blur: Double?
        var anim: String?
        var delay: Double?
    }

    /// The bundle holding paywall-art.json: SwiftPM's `Bundle.module`, or,
    /// installed through CocoaPods, the `NimbusCashier.bundle` resource
    /// bundle (inside the pod's framework, or in the app when linked
    /// statically).
    static var resources: Bundle {
        #if SWIFT_PACKAGE
        return Bundle.module
        #else
        let host = Bundle(for: BundleToken.self)
        for base in [host, Bundle.main] {
            if let url = base.url(forResource: "NimbusCashier", withExtension: "bundle"), let bundle = Bundle(url: url) {
                return bundle
            }
        }
        return host
        #endif
    }

    private final class BundleToken {}

    /// Every illustration by name, read once.
    static let scenes: [String: [Shape]] = {
        guard let url = resources.url(forResource: "paywall-art", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let scenes = try? JSONDecoder().decode([String: [Shape]].self, from: data) else { return [:] }
        return scenes
    }()

    // MARK: Colour tokens

    /// 0–255 channels (rounded, as the web draws them) and alpha.
    struct RGBA: Equatable, Sendable {
        var r: Int, g: Int, b: Int, a: Double

        var color: Color { Color(.sRGB, red: Double(r) / 255, green: Double(g) / 255, blue: Double(b) / 255, opacity: a) }

        /// The web's `rgba(…)` string, for comparing against it.
        var css: String {
            let alpha = (a * 1000).rounded() / 1000
            let text = alpha == alpha.rounded() ? String(Int(alpha)) : String(alpha)
            return "rgba(\(r), \(g), \(b), \(text))"
        }
    }

    private static let token = try! NSRegularExpression(pattern: #"^(AT|A|T|B|S|M|#[0-9a-fA-F]{6})([+-]\d+)?(?:\*([\d.]+))?(?:@([\d.]+))?$"#)

    /// Resolves a token like "A+40*0.8@0.5" (base colour; hue shift in
    /// degrees; HSL lightness multiplier; alpha multiplier) against the
    /// palette (A, AT, T, B, S, M → hex). nil is transparent. Matches the
    /// web's `artColor`.
    static func color(_ token: String, palette: [String: String]) -> RGBA? {
        let ns = token as NSString
        guard let m = Self.token.firstMatch(in: token, range: NSRange(location: 0, length: ns.length)) else { return nil }
        func group(_ i: Int) -> String? { m.range(at: i).location == NSNotFound ? nil : ns.substring(with: m.range(at: i)) }
        let name = group(1) ?? ""
        let base = name.hasPrefix("#") ? name : palette[name] ?? "#000000"
        var (r, g, b, a) = rgba(base) ?? (0, 0, 0, 1)
        let shift = group(2).flatMap(Double.init)
        let light = group(3).flatMap(Double.init)
        if shift != nil || light != nil {
            let (h, s, l) = hsl(r, g, b)
            (r, g, b) = rgb(h + (shift ?? 0), s, min(1, max(0, l * (light ?? 1))))
        }
        if let alpha = group(4).flatMap(Double.init) { a *= alpha }
        return RGBA(r: Int(r.rounded()), g: Int(g.rounded()), b: Int(b.rounded()), a: a)
    }

    /// "#RGB", "#RRGGBB" or "#RRGGBBAA" → 0–255 channels and alpha.
    private static func rgba(_ hex: String) -> (Double, Double, Double, Double)? {
        guard hex.hasPrefix("#") else { return nil }
        var s = String(hex.dropFirst())
        guard [3, 6, 8].contains(s.count), s.allSatisfy(\.isHexDigit) else { return nil }
        if s.count == 3 { s = s.map { "\($0)\($0)" }.joined() }
        guard let n = UInt32(s.prefix(6), radix: 16) else { return nil }
        let a = s.count == 8 ? Double(UInt32(s.suffix(2), radix: 16) ?? 255) / 255 : 1
        return (Double((n >> 16) & 255), Double((n >> 8) & 255), Double(n & 255), a)
    }

    private static func hsl(_ r: Double, _ g: Double, _ b: Double) -> (Double, Double, Double) {
        let r = r / 255, g = g / 255, b = b / 255
        let mx = max(r, g, b), mn = min(r, g, b), l = (mx + mn) / 2
        if mx == mn { return (0, 0, l) }
        let d = mx - mn, s = l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn)
        let h = mx == r ? (g - b) / d + (g < b ? 6 : 0) : mx == g ? (b - r) / d + 2 : (r - g) / d + 4
        return (h * 60, s, l)
    }

    private static func rgb(_ h: Double, _ s: Double, _ l: Double) -> (Double, Double, Double) {
        let h = ((h.truncatingRemainder(dividingBy: 360)) + 360).truncatingRemainder(dividingBy: 360) / 360
        if s == 0 { return (l * 255, l * 255, l * 255) }
        let q = l < 0.5 ? l * (1 + s) : l + s - l * s, p = 2 * l - q
        func f(_ t: Double) -> Double {
            let t = (t + 1).truncatingRemainder(dividingBy: 1)
            return t < 1.0 / 6 ? p + (q - p) * 6 * t : t < 0.5 ? q : t < 2.0 / 3 ? p + (q - p) * (2.0 / 3 - t) * 6 : p
        }
        return (f(h + 1.0 / 3) * 255, f(h) * 255, f(h - 1.0 / 3) * 255)
    }

    // MARK: Paths

    /// SVG path data using M, L, C and Z with absolute coordinates.
    static func path(_ d: String) -> Path {
        var p = Path()
        var nums: [Double] = []
        var command: Character?
        func flush() {
            switch command {
            case "M":
                var i = 0
                while i + 1 < nums.count {
                    let pt = CGPoint(x: nums[i], y: nums[i + 1])
                    // Pairs after the first are implicit line-tos, as in SVG.
                    if i == 0 { p.move(to: pt) } else { p.addLine(to: pt) }
                    i += 2
                }
            case "L":
                var i = 0
                while i + 1 < nums.count { p.addLine(to: CGPoint(x: nums[i], y: nums[i + 1])); i += 2 }
            case "C":
                var i = 0
                while i + 5 < nums.count {
                    p.addCurve(to: CGPoint(x: nums[i + 4], y: nums[i + 5]),
                               control1: CGPoint(x: nums[i], y: nums[i + 1]), control2: CGPoint(x: nums[i + 2], y: nums[i + 3]))
                    i += 6
                }
            case "Z", "z":
                p.closeSubpath()
            default:
                break
            }
            nums = []
        }
        var number = ""
        func endNumber() {
            if let v = Double(number) { nums.append(v) }
            number = ""
        }
        for ch in d {
            if "MLCZmlcz".contains(ch) {
                endNumber()
                flush()
                command = Character(ch.uppercased())
            } else if ch == "-" {
                // A minus starts a new number (unless after an exponent).
                if !number.isEmpty && !number.hasSuffix("e") { endNumber() }
                number.append(ch)
            } else if ch.isNumber || ch == "." || ch == "e" {
                if ch == "." && number.contains(".") { endNumber() }
                number.append(ch)
            } else {
                endNumber()
            }
        }
        endNumber()
        flush()
        return p
    }

    /// A shape's outline on the canvas (before rotation).
    static func outline(_ s: Shape) -> Path {
        switch s.t {
        case "rect":
            let rect = CGRect(x: s.x ?? 0, y: s.y ?? 0, width: s.w ?? 0, height: s.h ?? 0)
            if let r = s.r, r > 0 { return Path(roundedRect: rect, cornerRadius: min(r, rect.width / 2, rect.height / 2)) }
            return Path(rect)
        case "circle":
            let r = s.r ?? 0
            return Path(ellipseIn: CGRect(x: (s.cx ?? 0) - r, y: (s.cy ?? 0) - r, width: 2 * r, height: 2 * r))
        case "ellipse":
            let rx = s.rx ?? 0, ry = s.ry ?? 0
            return Path(ellipseIn: CGRect(x: (s.cx ?? 0) - rx, y: (s.cy ?? 0) - ry, width: 2 * rx, height: 2 * ry))
        case "path":
            return path(s.d ?? "")
        default:
            return Path()
        }
    }

    /// Where a shape turns about: a rect's centre, else (cx, cy).
    static func centre(_ s: Shape) -> CGPoint {
        s.t == "rect" ? CGPoint(x: (s.x ?? 0) + (s.w ?? 0) / 2, y: (s.y ?? 0) + (s.h ?? 0) / 2) : CGPoint(x: s.cx ?? 0, y: s.cy ?? 0)
    }

    // MARK: Motion

    /// An `alternate` CSS animation's eased progress (0…1) at `t` seconds,
    /// after `delay`; 0 before it starts.
    static func swing(_ t: Double, duration: Double, delay: Double) -> Double {
        let tt = t - delay
        guard tt > 0, duration > 0 else { return 0 }
        let cycle = tt / duration
        let n = cycle.rounded(.down)
        var p = cycle - n
        if Int(n) % 2 == 1 { p = 1 - p }
        return 0.5 - cos(.pi * p) / 2
    }
}

/// Draws an illustration to cover its box (aspect-fill, centred), clipped.
/// Animated shapes move only when `animates`; otherwise all rest.
struct PaywallArtView: View {
    let name: String
    /// A, AT, T, B, S, M → hex.
    let palette: [String: String]
    let animates: Bool

    @State private var start = Date()

    var body: some View {
        let shapes = PaywallArt.scenes[name] ?? []
        let moving = animates && shapes.contains { $0.anim != nil }
        Group {
            if moving {
                TimelineView(.animation) { context in
                    canvas(shapes, time: context.date.timeIntervalSince(start))
                }
            } else {
                canvas(shapes, time: nil)
            }
        }
        .clipped()
        .accessibilityHidden(true)
    }

    private func canvas(_ shapes: [PaywallArt.Shape], time: Double?) -> some View {
        Canvas { ctx, size in
            let scale = max(size.width / PaywallArt.width, size.height / PaywallArt.height)
            ctx.translateBy(x: (size.width - PaywallArt.width * scale) / 2, y: (size.height - PaywallArt.height * scale) / 2)
            ctx.scaleBy(x: scale, y: scale)
            for shape in shapes { draw(shape, in: &ctx, scale: scale, time: time) }
        }
    }

    private func draw(_ s: PaywallArt.Shape, in ctx: inout GraphicsContext, scale: CGFloat, time: Double?) {
        var path = PaywallArt.outline(s)
        let bounds = path.boundingRect
        if let rot = s.rot, rot != 0 {
            let c = PaywallArt.centre(s)
            path = path.applying(CGAffineTransform(translationX: c.x, y: c.y).rotated(by: rot * .pi / 180).translatedBy(x: -c.x, y: -c.y))
        }
        var opacity = 1.0
        if let t = time, let anim = s.anim {
            let delay = s.delay ?? 0
            switch anim {
            case "twinkle": opacity = 1 - 0.75 * PaywallArt.swing(t, duration: 2.2, delay: delay)
            case "float": path = path.offsetBy(dx: 0, dy: -6 * PaywallArt.swing(t, duration: 3.4, delay: delay))
            case "drift": path = path.offsetBy(dx: 14 * PaywallArt.swing(t, duration: 9, delay: delay), dy: 0)
            case "spin":
                let c = CGPoint(x: s.cx ?? 200, y: s.cy ?? 130)
                let angle = (t / 70).truncatingRemainder(dividingBy: 1) * 2 * .pi
                path = path.applying(CGAffineTransform(translationX: c.x, y: c.y).rotated(by: angle).translatedBy(x: -c.x, y: -c.y))
            default: break
            }
        }
        ctx.drawLayer { layer in
            layer.opacity = opacity
            if let blur = s.blur, blur > 0 {
                // SVG blurs with stdDeviation blur/2 in canvas units; SwiftUI's
                // radius (in points) reads about half as strong, so it is
                // doubled to match the web.
                layer.addFilter(.blur(radius: blur * scale))
            }
            if let fill = s.fill, let shading = shading(fill, bounds: bounds) {
                layer.fill(path, with: shading)
            }
            if let stroke = s.stroke, let c = PaywallArt.color(stroke, palette: palette) {
                layer.stroke(path, with: .color(c.color), lineWidth: s.sw ?? 1)
            }
        }
    }

    private func shading(_ paint: PaywallArt.Paint, bounds: CGRect) -> GraphicsContext.Shading? {
        switch paint {
        case .token(let t):
            guard t != "none", let c = PaywallArt.color(t, palette: palette) else { return nil }
            return .color(c.color)
        case .linear(let g):
            let stops = g.stops.enumerated().map { i, t in
                SwiftUI.Gradient.Stop(color: PaywallArt.color(t, palette: palette)?.color ?? .clear,
                                      location: Double(i) / Double(max(1, g.stops.count - 1)))
            }
            // CSS-like angle (180 = top → bottom) across the shape's box, as SVG's objectBoundingBox.
            let rad = (g.angle - 90) * .pi / 180
            let from = CGPoint(x: bounds.minX + (0.5 - cos(rad) / 2) * bounds.width, y: bounds.minY + (0.5 - sin(rad) / 2) * bounds.height)
            let to = CGPoint(x: bounds.minX + (0.5 + cos(rad) / 2) * bounds.width, y: bounds.minY + (0.5 + sin(rad) / 2) * bounds.height)
            return .linearGradient(SwiftUI.Gradient(stops: stops), startPoint: from, endPoint: to)
        }
    }
}
